#include <linux/netdevice.h>
#include <linux/err.h>

int bnep_add_connection(struct bnep_connadd_req *req, struct socket *sock) {
    struct net_device *dev;
    int result = -ENOMEM;

    if (!req || !sock) {
        return -EINVAL;
    }

    dev = alloc_netdev(0, "bnep%d", NET_NAME_UNKNOWN, ether_setup);
    if (!dev) {
        return -ENOMEM;
    }

    dev->priv = kzalloc(sizeof(struct bnep_session), GFP_KERNEL);
    if (!dev->priv) {
        free_netdev(dev);
        return -ENOMEM;
    }

    // Initialize session structure
    struct bnep_session *session = dev->priv;
    session->dev = dev;
    session->sock = sock;

    // Set up source and destination addresses
    memcpy(session->src_addr, req->src, BNEP_ADDR_LEN);
    memcpy(session->dst_addr, req->dst, BNEP_ADDR_LEN);

    // Check if a session already exists for the destination address
    if (bnep_session_exists(session->dst_addr)) {
        if (bnep_session_connected(session->dst_addr)) {
            kfree(dev->priv);
            free_netdev(dev);
            return -EEXIST;
        }
    }

    // Set up multicast and protocol filters if configured
    if (req->flags & BNEP_CONNADD_FLAG_MULTICAST) {
        dev->flags |= IFF_MULTICAST;
    }

    if (req->flags & BNEP_CONNADD_FLAG_PROTO_FILTER) {
        // Setup protocol filters
    }

    // Register the network device
    result = register_netdev(dev);
    if (result < 0) {
        kfree(dev->priv);
        free_netdev(dev);
        return result;
    }

    // Create a kernel thread to handle the session
    session->task = kthread_run(bnep_session_handler, session, "bnep_session");
    if (IS_ERR(session->task)) {
        unregister_netdev(dev);
        kfree(dev->priv);
        free_netdev(dev);
        return PTR_ERR(session->task);
    }

    // Update the request structure with the device name
    snprintf(req->dev_name, IFNAMSIZ, "%s", dev->name);

    return 0;
}
